                set.put(value);
                System.out.println(set);
            } else if (op.equals("remove")) {
                set.remove(value);
                System.out.println(set);
            } else if (op.equals("contains")) {
                System.out.println(set.contains(value));
            }
        }
    }
}

class HashSetOA {
    private Integer[] table;
    private final Integer DELETED = Integer.MIN_VALUE;

    public HashSetOA(int size) {
        table = new Integer[size];
    }

    private int hash(int key) {
        return key % table.length;
    }

    public void put(int value) {
        int firstDeleted = -1;

        for (int i = 0; i < table.length; i++) {
            int pos = (hash(value) + i) % table.length;

            if (table[pos] == null) {
                if (firstDeleted != -1) table[firstDeleted] = value;
                else table[pos] = value;
                return;
            }

            if (table[pos].equals(DELETED)) {
                if (firstDeleted == -1) firstDeleted = pos;
            } else if (table[pos] == value) {
                return;
            }
        }

        if (firstDeleted != -1) {
            table[firstDeleted] = value;
        }
    }

    public void remove(int value) {
        for (int i = 0; i < table.length; i++) {
            int pos = (hash(value) + i) % table.length;

            if (table[pos] == null) return;
            if (!table[pos].equals(DELETED) && table[pos] == value) {
                table[pos] = DELETED;
                return;
            }
        }
    }

    public boolean contains(int value) {
        for (int i = 0; i < table.length; i++) {
            int pos = (hash(value) + i) % table.length;

            if (table[pos] == null) return false;
            if (!table[pos].equals(DELETED) && table[pos] == value) return true;
        }
        return false;
    }

    public String toString() {
        String[] out = new String[table.length];
        for (int i = 0; i < table.length; i++) {
            if (table[i] == null || table[i].equals(DELETED)) out[i] = "null";
            else out[i] = String.valueOf(table[i]);
        }
        return Arrays.toString(out);
    }
}
