import java.util.Arrays;
import java.util.Scanner;

public class Solution {

    public static void countingSortPorPar(int[] arr, int exp) {
        int n = arr.length;
        int[] output = new int[n];
        int[] count = new int[100]; // pares de 00 a 99

        for (int i = 0; i < n; i++) {
            int par = (arr[i] / exp) % 100;
            count[par]++;
        }

        for (int i = 1; i < 100; i++) {
            count[i] += count[i - 1];
        }

        for (int i = n - 1; i >= 0; i--) {
            int par = (arr[i] / exp) % 100;
            output[count[par] - 1] = arr[i];
            count[par]--;
        }

        for (int i = 0; i < n; i++) {
            arr[i] = output[i];
        }
    }

