  public void dfs(int node, int par) {
    this.visited[node] = true;
    this.reachableFromZero++;
    for(Edge edge: getEdgesFromVertex(node)) {
      if(!visited[edge.getEndNode()]) dfs(edge.getEndNode(), node);
